from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Attr(EmssimCommand):
    def __init__(self, method="attr", timeout=60, rpc_connection_name='localRPC'):
        super(Attr, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Attr, self).on_new_data(**data)
        if "table" in data:
            self._ret['attributes_details'] = self.parse_table_with_unique_key_to_dictionary(data['table'], "ATTRIBUTE")
        elif ("status" in data):
            self._ret["status"] = data["status"]
